css:
/* Styles généraux pour un document de synthèse */
body {
    font-family: 'Arial', sans-serif;
    font-size: 11pt;
    line-height: 1.6;
    margin: 40px; /* Marges pour l'impression */
}
.header, .footer {
    text-align: center;
    margin-bottom: 20px;
    font-size: 10pt;
}
.header h1 {
    font-size: 18pt;
    margin-bottom: 5px;
    color: #2c3e50;
}
.section {
    margin-bottom: 30px;
    padding-bottom: 15px;
    border-bottom: 1px solid #eee;
}
.section-title {
    font-weight: bold;
    color: #2c3e50;
    margin-top: 25px;
    margin-bottom: 15px;
    font-size: 14pt;
}
.data-row {
    display: flex;
    margin-bottom: 5px;
}
.data-label {
    font-weight: bold;
    width: 180px; /* Largeur fixe pour les libellés */
    flex-shrink: 0;
}
.data-value {
    flex-grow: 1;
}
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
}
table, th, td {
    border: 1px solid #ddd;
}
th, td {
    padding: 8px;
    text-align: left;
}
th {
    background-color: #f2f2f2;
    font-weight: bold;
}
.no-data {
    font-style: italic;
    color: #777;
}
